-- ============================================================================
-- OLATO PLATFORM: CLEAN NUMERICAL SCHEMA & SEED (IDs: 1, 2, 3, 4, 5...)
-- Includes ALL Pakistani Banks, Digital Wallets (Easypaisa, JazzCash, SadaPay, NayaPay, Zindigi)
-- ============================================================================

-- 1. DROP OLD TABLES
DROP TABLE IF EXISTS public.saved_places CASCADE;
DROP TABLE IF EXISTS public.discounts CASCADE;
DROP TABLE IF EXISTS public.place_tags CASCADE;
DROP TABLE IF EXISTS public.place_categories CASCADE;
DROP TABLE IF EXISTS public.places CASCADE;
DROP TABLE IF EXISTS public.discount_providers CASCADE;
DROP TABLE IF EXISTS public.tags CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;

-- 2. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "postgis";

-- 3. CATEGORIES (IDs: 1, 2, 3...)
CREATE TABLE public.categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    slug TEXT NOT NULL UNIQUE,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 4. TAGS (IDs: 1, 2, 3...)
CREATE TABLE public.tags (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    slug TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 5. DISCOUNT PROVIDERS (Banks, Digital Wallets & Card Networks)
CREATE TABLE public.discount_providers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    slug TEXT NOT NULL UNIQUE,
    provider_type TEXT NOT NULL DEFAULT 'bank' CHECK (provider_type IN ('bank', 'digital_wallet', 'card_network', 'platform')),
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 6. PLACES (IDs: 1, 2, 3, 4, 5...)
CREATE TABLE public.places (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    description TEXT DEFAULT '',
    why_this_spot_is_good TEXT DEFAULT '',
    address TEXT NOT NULL,
    area TEXT NOT NULL DEFAULT 'Gulberg',
    city TEXT NOT NULL DEFAULT 'Lahore',
    location GEOGRAPHY(POINT, 4326) NOT NULL,
    phone TEXT,
    opening_hours TEXT,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_places_location ON public.places USING GIST (location);

-- 7. PLACE CATEGORIES (M:N)
CREATE TABLE public.place_categories (
    place_id BIGINT NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
    category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT,
    is_primary BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY (place_id, category_id)
);

-- 8. PLACE TAGS (M:N)
CREATE TABLE public.place_tags (
    place_id BIGINT NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
    tag_id BIGINT NOT NULL REFERENCES public.tags(id) ON DELETE RESTRICT,
    PRIMARY KEY (place_id, tag_id)
);

-- 9. DISCOUNTS (IDs: 1, 2, 3... with simple place_id: 1, 2, 3...)
CREATE TABLE public.discounts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    place_id BIGINT NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
    provider_id BIGINT REFERENCES public.discount_providers(id) ON DELETE SET NULL,
    bank_card TEXT DEFAULT '',
    title TEXT NOT NULL,
    discount_type TEXT NOT NULL DEFAULT 'percentage',
    discount_value NUMERIC(10,2) DEFAULT 0,
    eligibility_type TEXT NOT NULL DEFAULT 'all',
    is_student_eligible BOOLEAN NOT NULL DEFAULT false,
    details TEXT DEFAULT '',
    terms TEXT[] NOT NULL DEFAULT '{}',
    redemption_instructions TEXT[] NOT NULL DEFAULT '{}',
    start_date DATE NOT NULL DEFAULT CURRENT_DATE,
    end_date DATE NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT true,
    last_verified_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_discounts_place_id ON public.discounts(place_id);
CREATE INDEX IF NOT EXISTS idx_discounts_provider_id ON public.discounts(provider_id);
CREATE INDEX IF NOT EXISTS idx_discounts_bank_card ON public.discounts(bank_card);

-- 10. SAVED PLACES (Bookmarks)
CREATE TABLE public.saved_places (
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    place_id BIGINT NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, place_id)
);

-- 11. ROW LEVEL SECURITY (RLS)
ALTER TABLE public.places ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.place_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.place_tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.discount_providers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.discounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.saved_places ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public read places" ON public.places FOR SELECT USING (true);
CREATE POLICY "Public read categories" ON public.categories FOR SELECT USING (true);
CREATE POLICY "Public read place_categories" ON public.place_categories FOR SELECT USING (true);
CREATE POLICY "Public read tags" ON public.tags FOR SELECT USING (true);
CREATE POLICY "Public read place_tags" ON public.place_tags FOR SELECT USING (true);
CREATE POLICY "Public read discount_providers" ON public.discount_providers FOR SELECT USING (true);
CREATE POLICY "Public read discounts" ON public.discounts FOR SELECT USING (true);
CREATE POLICY "Users read saved_places" ON public.saved_places FOR SELECT USING (auth.uid() = user_id);

