-- PLACES 1 to 40 (CONTINENTAL & INTERNATIONAL)
INSERT INTO public.places (id, name, slug, description, why_this_spot_is_good, address, area, city, location, phone, opening_hours)
VALUES
  (1, 'Café Aylanto', 'cafe-aylanto', 'Premier Mediterranean fine dining featuring grilled fish, aged steaks, and brick-oven pizzas.', 'Exquisite courtyard ambiance under fairy-lit trees with signature grilled red snapper and Moroccan chicken.', '12 C-1 MM Alam Road, Gulberg III', 'MM Alam Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3524, 31.5128), 4326)::geography, '+92 42 35751886', '12:30 PM - 12:00 AM'),
  (2, 'Paola’s Cosa Nostra', 'paolas-cosa-nostra', 'Authentic Italian culinary institution serving handmade pasta, antipasti, and classic gelato.', 'Rustic Italian trattoria setting famous for handcrafted ravioli, burrata salads, and wood-fired focaccia.', '23-A Dr Mateen Fatima Road, Gulberg II', 'Dr Mateen Fatima Road, Gulberg', 'Lahore', ST_SetSRID(ST_MakePoint(74.3541, 31.5192), 4326)::geography, '+92 42 35757041', '01:00 PM - 11:30 PM'),
  (3, 'The Mad Italian', 'the-mad-italian-gulberg', 'Vibrant Italian kitchen known for artisanal Neapolitan pizza and decadent pasta plates.', 'Casual energetic bistro with blistered sourdough Neapolitan crusts and creamy truffle pastas.', 'Hali Road, Gulberg III', 'Hali Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3488, 31.5271), 4326)::geography, '+92 300 0700888', '01:00 PM - 12:00 AM'),
  (4, 'The Mad Italian DHA', 'the-mad-italian-dha', 'DHA outpost of The Mad Italian offering artisanal pizzas and Italian street delicacies.', 'Modern cozy dining room serving hot stone-baked pizzas and fresh garlic knots in the heart of DHA Phase 3.', 'Z Block, Commercial Area, DHA Phase 3', 'Z Block, DHA Phase 3', 'Lahore', ST_SetSRID(ST_MakePoint(74.3942, 31.4795), 4326)::geography, '+92 300 0700889', '01:00 PM - 12:00 AM'),
  (5, 'La Cornucopia Ristorante', 'la-cornucopia-cantt', 'Upscale Cantt dining destination offering refined European continental courses and desserts.', 'Serene military cantonment ambiance with prime tenderloins and delicate European desserts.', 'Khursheed Alam Road, Cantt', 'Khursheed Alam Road, Cantt', 'Lahore', ST_SetSRID(ST_MakePoint(74.3821, 31.5492), 4326)::geography, '+92 42 36683888', '12:00 PM - 11:30 PM'),
  (6, 'Ox & Grill Steak House Lahore', 'ox-and-grill-gulberg', 'Sizzling steakhouse serving prime beef tenderloins, cowboy steaks, and chicken platters.', 'Lively steakhouse experience famous for sizzling cast-iron skillet steaks with black pepper mushroom sauce.', 'Tariq Road, Gulberg III', 'Tariq Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3498, 31.5175), 4326)::geography, '+92 42 35759900', '12:30 PM - 12:00 AM'),
  (7, 'Carné Steakhouse', 'carne-steakhouse-gulberg', 'Gourmet butcher steakhouse specializing in dry-aged beef, wagyu cuts, and artisan sides.', 'Dimly lit masculine steakhouse luxury with imported prime cuts, bone marrow sides, and rich sauces.', 'Block T, Gulberg II', 'Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3512, 31.5235), 4326)::geography, '+92 301 8444455', '06:00 PM - 12:30 AM'),
  (8, 'Butcher’s Steakhouse', 'butchers-steakhouse-gulberg', 'Specialist meat house serving charcoal-grilled steaks, gourmet burgers, and smoked cuts.', 'Rustic wood and brick venue with perfectly seared ribeyes and creamy parmesan mashed potatoes.', 'Block P, Gulberg II', 'Block P, Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3538, 31.5210), 4326)::geography, '+92 42 35778899', '01:00 PM - 12:00 AM'),
  (9, 'Steak Studio - Canal Branch', 'steak-studio-canal', 'Canal road dining spot offering generous skillet steaks, loaded burgers, and pasta bowls.', 'Casual family-friendly steakhouse with friendly portions and great value combos along Canal Bank Road.', 'Canal Bank Road / Iqbal Avenue', 'Canal Bank Road / Iqbal Avenue', 'Lahore', ST_SetSRID(ST_MakePoint(74.2485, 31.4421), 4326)::geography, '+92 321 4455667', '01:00 PM - 01:00 AM'),
  (10, 'El Momento', 'el-momento-dha', 'High-end modern steakhouse with theatrical table-side carving and live cooking displays.', 'Glamorous interior with dry-aged tomahawk cuts, flame-torched presentations, and premium dining vibes.', 'Sector Z, Commercial Area, DHA Phase 3', 'DHA Phase 3', 'Lahore', ST_SetSRID(ST_MakePoint(74.3955, 31.4782), 4326)::geography, '+92 311 1100333', '01:00 PM - 01:00 AM'),
  (11, 'The Carnivore', 'the-carnivore-dha6', 'Dedicated meat boutique serving slow-smoked brisket, beef ribs, and prime tenderloins.', 'Authentic oak-wood Texas-style smoked barbecue and tender steaks for true meat purists in DHA Phase 6.', 'Sector C, Commercial Area, DHA Phase 6', 'DHA Phase 6', 'Lahore', ST_SetSRID(ST_MakePoint(74.4382, 31.4621), 4326)::geography, '+92 320 9999888', '05:00 PM - 01:00 AM'),
  (12, 'Rare Steakhouse', 'rare-steakhouse-dha5', 'Boutique upscale steak lounge featuring bespoke cuts of imported Angus beef and sea bass.', 'Intimate romantic lighting, velvet booths, and melt-in-your-mouth fillets paired with herb butters.', 'Sector CCA, DHA Phase 5', 'DHA Phase 5', 'Lahore', ST_SetSRID(ST_MakePoint(74.4095, 31.4705), 4326)::geography, '+92 42 37180022', '06:30 PM - 12:30 AM'),
  (13, 'The Brasserie', 'the-brasserie-gulberg', 'French-inspired modern bistro serving gourmet sandwiches, steaks, and decadent brunch.', 'Sophisticated Paris-meets-Lahore brasserie featuring duck confit, eggs benedict, and artisan coffee.', 'Main Boulevard, Gulberg III', 'Main Boulevard, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3475, 31.5160), 4326)::geography, '+92 42 35789888', '08:30 AM - 12:00 AM'),
  (14, 'Fuschia Kitchen', 'fuschia-kitchen-gulberg', 'Contemporary Pan-Asian bistro celebrated for modern Thai and dim sum courses.', 'Sleek modern red-accented dining room with crispy prawn wasabi, fiery Tom Yum, and Thai red curries.', 'Hali Road, Gulberg III', 'Hali Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3482, 31.5285), 4326)::geography, '+92 42 35755344', '12:30 PM - 11:30 PM'),
  (15, 'Alchemy', 'alchemy-gulberg', 'Avant-garde gastronomy kitchen fusing international flavors with molecular presentation.', 'Cutting-edge culinary artistry with surprising textures, smoke-infused dishes, and signature mocktails.', 'Main Boulevard, Gulberg III', 'Main Boulevard, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3468, 31.5182), 4326)::geography, '+92 300 1234567', '07:00 PM - 12:30 AM'),
  (16, 'Bon Vivant Palais', 'bon-vivant-palais', 'Majestic multi-level international dining destination with lavish chandeliers and world buffets.', 'Palatial architecture with royal international buffet spreads spanning continental, Chinese, and BBQ.', 'Sir Syed Road, Gulberg III', 'Sir Syed Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3510, 31.5152), 4326)::geography, '+92 42 35759911', '12:00 PM - 12:00 AM'),
  (17, 'Urban Kitchen', 'urban-kitchen-gulberg', 'Trendsetting casual bistro serving loaded burgers, pasta bowls, and artisan milkshakes.', 'Vibrant urban industrial vibe with mouthwatering comfort food favorites and outdoor patio seating.', 'Block L, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3520, 31.5165), 4326)::geography, '+92 42 35752233', '01:00 PM - 01:00 AM'),
  (18, 'Veranda Bistro', 'veranda-bistro-dha5', 'Acclaimed open-air courtyard restaurant celebrated for live barbecue and continental buffets.', 'Lush candlelit courtyard dining under night skies with live international carving stations.', 'Sector J, Phase 5, DHA', 'DHA Phase 5', 'Lahore', ST_SetSRID(ST_MakePoint(74.4112, 31.4680), 4326)::geography, '+92 42 37180055', '12:30 PM - 12:00 AM'),
  (19, 'Rina’s Kitchenette', 'rinas-kitchenette-dha', 'Charming homegrown bakery and bistro known for caramel cakes, buttermilk chicken, and aglio olio.', 'Cozy pastel-hued neighborhood sanctuary famous for fresh artisan sourdough, savory pies, and caramel cake.', 'Sector Y, DHA Phase 3', 'Y Block, DHA Phase 3', 'Lahore', ST_SetSRID(ST_MakePoint(74.3912, 31.4820), 4326)::geography, '+92 42 35742200', '12:00 PM - 11:30 PM'),
  (20, 'For the Table by Terra', 'for-the-table-terra', 'Seasonal farm-to-table culinary project highlighting artisanal sharing plates and sourdough.', 'Minimalist warm aesthetic with communal sharing platters, handcrafted burrata, and botanical drinks.', 'Y Block, DHA Phase 3', 'Y Block, DHA Phase 3', 'Lahore', ST_SetSRID(ST_MakePoint(74.3925, 31.4815), 4326)::geography, '+92 300 8477788', '01:00 PM - 11:00 PM'),
  (21, 'Garden Of Eve', 'garden-of-eve-dha', 'Botanical garden café and restaurant serving fusion bowls, specialty coffees, and artisan desserts.', 'Dreamy floral greenhouse setting with light-drenched glass panels, ideal for brunch and coffee dates.', 'Commercial Area, DHA Phase 4', 'DHA Phase 4', 'Lahore', ST_SetSRID(ST_MakePoint(74.3855, 31.4721), 4326)::geography, '+92 301 9998877', '11:00 AM - 12:00 AM'),
  (22, 'The Continental – Global Gastronomy', 'the-continental-raya', 'Luxury golf-resort dining destination overlooking the Fairways at DHA Raya.', 'Panoramic golf course views paired with lobster ravioli, tenderloin steaks, and imported mocktails.', 'Fairways Commercial, DHA Raya, Phase 6', 'Raya Fairways, DHA Phase 6', 'Lahore', ST_SetSRID(ST_MakePoint(74.4510, 31.4420), 4326)::geography, '+92 42 37340011', '01:00 PM - 12:00 AM'),
  (23, 'Crosta', 'crosta-cantt', 'Artisanal pizzeria and Italian deli in Cantonment serving fermented sourdough pizzas.', 'Crispy wood-fired sourdough crusts with fresh San Marzano tomato sauce and fresh fior di latte cheese.', 'CSD / Aziz Bhatti Road, Cantt', 'CSD / Aziz Bhatti Road, Cantt', 'Lahore', ST_SetSRID(ST_MakePoint(74.3888, 31.5515), 4326)::geography, '+92 302 4455888', '01:00 PM - 11:30 PM'),
  (24, 'Café Delice', 'cafe-delice-model-town', 'Cozy Model Town bistro serving European brunch, crepes, and specialty hot chocolates.', 'Quiet leafy neighborhood café with French crepes, artisan breakfast spreads, and tranquil vibes.', 'Central Commercial Market, Model Town', 'Model Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.3225, 31.4880), 4326)::geography, '+92 42 35882211', '09:00 AM - 11:30 PM'),
  (25, 'Arcadian Café - DHA Raya', 'arcadian-cafe-raya', 'Famous upscale eatery featuring signature stuffed chicken breast, fiery dragon chicken, and steaks.', 'Stunning modern lakeside architecture with Arcadian iconic red dragon chicken and basil chicken.', 'DHA Raya Commercial, Phase 6', 'DHA Raya', 'Lahore', ST_SetSRID(ST_MakePoint(74.4525, 31.4410), 4326)::geography, '+92 42 37340055', '12:30 PM - 12:00 AM'),
  (26, 'Arcadian Café - Packages Mall', 'arcadian-cafe-packages', 'Mall destination for Arcadian favorites with family-sized booths and fast attentive service.', 'Convenient upscale retreat inside Packages Mall serving signature continental mains and molten lava cake.', 'Ground Floor, Packages Mall, Walton Road', 'Packages Mall', 'Lahore', ST_SetSRID(ST_MakePoint(74.3582, 31.4735), 4326)::geography, '+92 42 38302211', '12:00 PM - 11:30 PM'),
  (27, 'Café Zouk', 'cafe-zouk-gulberg', 'Lahore legendary nightlife-style dining cafe established over two decades ago.', 'Iconic nostalgic mood lighting, finger-licking chicken cordon bleu, and signature spicy thai noodles.', '7-D MM Alam Road, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3508, 31.5140), 4326)::geography, '+92 42 35756475', '01:00 PM - 01:00 AM'),
  (28, 'English Tea House', 'english-tea-house-gulberg', 'Vintage Victorian tea house known for traditional British high tea, scones, and shepherd’s pie.', 'Quaint Victorian brick fireplace setting with tiered afternoon tea platters, clotted cream, and jams.', '24 K, Sir Syed Road, Gulberg II', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3528, 31.5178), 4326)::geography, '+92 42 35715535', '08:30 AM - 12:00 AM'),
  (29, 'Bistro 201', 'bistro-201-dha6', 'Rooftop and indoor continental dining offering skyline views and multi-cuisine mains.', 'Spectacular rooftop sunset vistas paired with grilled steaks, wood-fired chicken, and mocktails.', 'Main Boulevard, DHA Phase 6', 'DHA Phase 6', 'Lahore', ST_SetSRID(ST_MakePoint(74.4370, 31.4645), 4326)::geography, '+92 42 37180201', '06:00 PM - 01:00 AM'),
  (30, 'The Patio', 'the-patio-gulberg', 'Boutique outdoor dining courtyard offering fresh seasonal seafood and continental mains.', 'Relaxing al-fresco terrace with sea bass skewers, balsamic beef medallions, and warm apple tarts.', 'Near Mini Market, Gulberg II', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3550, 31.5220), 4326)::geography, '+92 300 4455112', '01:00 PM - 11:30 PM'),
  (31, 'Novu', 'novu-gulberg', 'Pan-Asian wok house known for quick, explosive bowls of Kung Pao and Singaporean noodles.', 'Casual wok bar with sizzling noodles, crispy beef bowls, and addictive dynamite prawns.', 'Shop 3, Block C-3, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3545, 31.5150), 4326)::geography, '+92 42 35785500', '12:30 PM - 12:00 AM'),
  (32, 'Caspian Sea', 'caspian-sea-johar-town', 'Johar Town continental and seafood specialist serving fish and chips, prawns, and steaks.', 'Comfortable dining lounge in Johar Town known for crispy battered fish and sizzling pepper steaks.', 'Commercial Area, Block G, Johar Town', 'Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2715, 31.4670), 4326)::geography, '+92 42 35312244', '01:00 PM - 12:00 AM'),
  (33, 'P.F. Chang’s', 'pf-changs-lahore', 'World-renowned American Asian dining giant known for Chang’s Lettuce Wraps and dynamite shrimp.', 'High-energy modern Asian dining with iconic horse statues, wok-fired chicken, and hand-folded dumplings.', '17-C1 MM Alam Road, Gulberg III', 'MM Alam Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3515, 31.5132), 4326)::geography, '+92 42 35759977', '12:00 PM - 12:00 AM'),
  (34, 'Yum Chinese & Thai', 'yum-chinese-and-thai-gulberg', 'Premier traditional Chinese and Thai dining offering peking duck, dim sum, and red curry.', 'Elegant Chinese oriental setting with private dining rooms, steamed dim sum, and sizzling beef platters.', '24 K, Sir Syed Road, Gulberg II', 'Sir Syed Road, Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3525, 31.5180), 4326)::geography, '+92 42 35715533', '12:30 PM - 12:00 AM'),
  (35, 'Sumo', 'sumo-japanese-gulberg', 'Authentic Japanese restaurant celebrated for teppanyaki live cooking, fresh sashimi, and sushi rolls.', 'Intimate Japanese teppanyaki counter theatre with fresh salmon rolls, wagyu beef, and prawn tempura.', 'Gulberg II / DHA', 'Gulberg / DHA', 'Lahore', ST_SetSRID(ST_MakePoint(74.3540, 31.5200), 4326)::geography, '+92 42 35754422', '01:00 PM - 11:30 PM'),
  (36, 'Wasabi', 'wasabi-gulberg', 'Contemporary Japanese and sushi destination serving creative maki rolls and bento sets.', 'Modern Japanese minimalist aesthetic with crispy California rolls, spicy salmon, and teriyaki bowls.', 'MM Alam Road, Gulberg III', 'Gulberg / DHA', 'Lahore', ST_SetSRID(ST_MakePoint(74.3518, 31.5145), 4326)::geography, '+92 300 8435566', '01:00 PM - 12:00 AM'),
  (37, 'Taipei Cuisine', 'taipei-cuisine-gulberg', 'Authentic Taiwanese and oriental cooking known for dumplings, beef hot pots, and scallion pancakes.', 'Understated authentic haven for Taiwanese foodies craving handmade dumplings and savory broths.', 'Block P, Gulberg II', 'MM Alam Road, Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3532, 31.5215), 4326)::geography, '+92 42 35773322', '12:30 PM - 11:30 PM'),
  (38, 'Opium Thai', 'opium-thai-gulberg', 'Sensory Thai dining journey with fresh lemongrass broths, pad thai, and spicy basil chicken.', 'Atmospheric Thai retreat with delicate fragrant curries, coconut soups, and sweet mango sticky rice.', 'Near Mini Market, Gulberg II', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3538, 31.5230), 4326)::geography, '+92 301 8443322', '01:00 PM - 12:00 AM'),
  (39, 'Bamboo Union', 'bamboo-union-gulberg', 'Casual high-speed Pan-Asian kitchen with crowd-favorite crispy beef, dynamite sushi, and pad thai.', 'Buzzing energetic Asian street kitchen with generous portions and fast, mouthwatering flavors.', 'Main Boulevard, Gulberg III', 'Main Boulevard, Gulberg', 'Lahore', ST_SetSRID(ST_MakePoint(74.3485, 31.5170), 4326)::geography, '+92 301 8485566', '12:30 PM - 12:30 AM'),
  (40, 'Monal Lahore', 'monal-lahore-liberty', 'Rooftop restaurant perched high over Liberty Chowk offering panoramic city vistas and continental grill.', 'Breathtaking 360-degree city views from the top of Park Avenue, famous for evening skyline dinners.', 'Park Avenue Building, Liberty Chowk, Gulberg III', 'Liberty Chowk, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3450, 31.5115), 4326)::geography, '+92 42 35789988', '01:00 PM - 01:00 AM');

-- PLACES 41 to 60 (CAFÉS & COFFEE SHOPS)
INSERT INTO public.places (id, name, slug, description, why_this_spot_is_good, address, area, city, location, phone, opening_hours)
VALUES
  (41, 'Contra Coffee Shop', 'contra-coffee-gulberg', 'Modernist specialty coffee boutique roasting single-origin Ethiopian and Colombian beans.', 'Sleek industrial chic aesthetics, pour-over masterclasses, and ultra-quiet booths for focused work.', 'Sir Syed Road, Gulberg II', 'Sir Syed Road, Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3530, 31.5190), 4326)::geography, '+92 300 0022334', '08:00 AM - 11:30 PM'),
  (42, 'Pulse Coffee Lahore', 'pulse-coffee-gulberg', 'Community-driven coffee collective serving cold brews, matcha lattes, and artisan toasties.', 'Vibrant creative crowd with high-speed internet, specialty espresso drinks, and warm banana bread.', 'Block P, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3542, 31.5165), 4326)::geography, '+92 302 8887766', '08:30 AM - 12:00 AM'),
  (43, 'HOUSE Coffee & Desserts', 'house-coffee-and-desserts', 'Aesthetic minimalist coffee lounge specializing in Basque burnt cheesecakes and Spanish cortados.', 'Warm sun-dappled interior with the best Basque burnt cheesecake in Lahore and velvety flat whites.', 'Block C1, Gulberg III', 'C1, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3510, 31.5148), 4326)::geography, '+92 321 4455888', '09:00 AM - 12:00 AM'),
  (44, 'Coffee Tea & Company', 'coffee-tea-and-company', 'Lahore pioneer café offering vintage armchairs, herbal teas, and hot chocolate.', 'Nostalgic cozy sanctuary with plush couches, warm apple cider, and comforting chicken club sandwiches.', 'Mian Mehmood Ali Kasoori Road, Gulberg III', 'Mian Mehmood Ali Kasoori Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3560, 31.5110), 4326)::geography, '+92 42 35759144', '08:00 AM - 01:00 AM'),
  (45, 'Baraza Coffee', 'baraza-coffee-mall-1', 'Upscale espresso bar inside Mall 1 serving handcrafted cold brews and French pastries.', 'Chic outdoor patio inside Mall 1 with artisan coffee roasts and French butter croissants.', 'Mall 1, Main Boulevard, Gulberg III', 'Mall 1, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3490, 31.5170), 4326)::geography, '+92 300 8477112', '08:00 AM - 12:00 AM'),
  (46, '6.3coffee', '6-3-coffee-dha8', 'Modernist cube-architecture coffee lab serving scientific pour-overs in DHA Phase 8.', 'Architectural eye-candy with futuristic glass facades, quiet corners, and exceptional Colombian brews.', 'Sector C, Commercial Area, DHA Phase 8', 'DHA Phase 8', 'Lahore', ST_SetSRID(ST_MakePoint(74.4680, 31.4350), 4326)::geography, '+92 300 6363630', '09:00 AM - 11:30 PM'),
  (47, 'Green Door Coffee Cafe & Patisserie', 'green-door-coffee-johar', 'Johar Town patisserie retreat known for pastel green decor, macarons, and iced coffees.', 'Peaceful sanctuary in Johar Town featuring French eclairs, macarons, and study-friendly seating.', 'Block G, Phase 1, Johar Town', 'Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2730, 31.4685), 4326)::geography, '+92 300 4488221', '09:00 AM - 11:30 PM'),
  (48, 'Third Culture Coffee - Model Town', 'third-culture-coffee-model-town', 'Specialty coffee roastery in Model Town championing direct-trade beans and manual brews.', 'Lush garden view seating with precision espresso machines and single-origin aeropress flights.', 'Block C, Model Town', 'Model Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.3215, 31.4910), 4326)::geography, '+92 300 3334445', '08:00 AM - 11:00 PM'),
  (49, 'Chai & Coffee', 'chai-and-coffee-cantt', 'Cantt neighborhood meeting point serving traditional Karak chai alongside specialty flat whites.', 'Casual open-air verandah in Cantt combining clay-cup Karak chai with modern espresso and parathas.', 'Tufail Road, Cantt', 'Tufail Road, Cantt', 'Lahore', ST_SetSRID(ST_MakePoint(74.3790, 31.5450), 4326)::geography, '+92 42 36671122', '07:00 AM - 01:00 AM'),
  (50, 'Mocca Coffee', 'mocca-coffee-gulberg', 'Scandinavian-style coffee sanctuary celebrated for clean aesthetics, macaroons, and paninis.', 'Bright Nordic minimalism with healthy smoothie bowls, smoked chicken panini, and iced lattes.', 'Mall 94, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3512, 31.5130), 4326)::geography, '+92 42 35754488', '08:00 AM - 12:30 AM'),
  (51, 'Gloria Jean’s Coffees', 'gloria-jeans-gulberg', 'Worldwide Australian coffee franchise known for signature Irish nut cream and iced chillers.', 'Dependable co-working hub with fast internet, plenty of wall outlets, and rich caramel chillers.', 'Kasuri Road, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3555, 31.5120), 4326)::geography, '+92 42 35759922', '08:00 AM - 01:00 AM'),
  (52, 'Tim Hortons', 'tim-hortons-mall-one', 'Canadian coffee and donut icon famous for Double-Doubles, French Vanilla, and Timbits.', 'Bustling Canadian gathering spot with warm maple dip donuts and signature French Vanilla lattes.', 'Mall One, Main Boulevard, Gulberg III', 'Mall One, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3488, 31.5168), 4326)::geography, '+92 42 35780001', '07:00 AM - 02:00 AM'),
  (53, 'Butler’s Chocolate Café', 'butlers-chocolate-cafe-gulberg', 'Irish luxury chocolatier café offering gourmet truffles, decadent sundaes, and hot chocolate.', 'Lavish chocolate bliss where every hot coffee arrives with a complimentary artisan chocolate truffle.', 'Fortune Mall, MM Alam Road, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3520, 31.5135), 4326)::geography, '+92 42 35772522', '09:00 AM - 01:00 AM'),
  (54, 'Freddy’s Café', 'freddys-cafe-gulberg', 'Iconic MM Alam landmark known for giant beef burgers, continental platters, and desserts.', 'Historic Lahori culinary staple with deep mahogany booths, hot skillet brownies, and club steaks.', '12-C MM Alam Road, Gulberg III', 'MM Alam Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3522, 31.5125), 4326)::geography, '+92 42 35754416', '12:00 PM - 12:00 AM'),
  (55, 'Tandoori Tea & Co.', 'tandoori-tea-and-co', 'Street-luxe tea spot serving clay-baked tandoori chai, paratha rolls, and bun kebabs.', 'Sensational smoking hot clay pot tea infused with cardamom and served alongside spicy parathas.', 'Mian Mehmood Ali Kasoori Road, Gulberg III', 'Mian Mehmood Ali Kasoori Road', 'Lahore', ST_SetSRID(ST_MakePoint(74.3570, 31.5115), 4326)::geography, '+92 321 8877665', '04:00 PM - 03:00 AM'),
  (56, 'Chaye Gossip', 'chaye-gossip-gulberg', 'Late-night tea lounge with indoor and outdoor beanbag seating, serving savory snacks and chai.', 'Relaxed late-night youth hangout with Doodh Patti chai, Nutella parathas, and board games.', 'Block C-2, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3535, 31.5175), 4326)::geography, '+92 300 4455880', '05:00 PM - 04:00 AM'),
  (57, 'FiLLi Cafe', 'filli-cafe-johar', 'Dubai-originated tea chain famous for signature Zafran (Saffron) tea and burgers.', 'Addictive aromatic saffron-infused hot tea served in Johar Town alongside gourmet wraps.', 'Commercial Area, Phase 1, Johar Town', 'Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2745, 31.4678), 4326)::geography, '+92 42 35310088', '10:00 AM - 02:00 AM'),
  (58, 'Terrace Café', 'terrace-cafe-johar', 'Rooftop open-air terrace in Johar Town with cozy lighting, cold frappes, and pizzas.', 'Gentle outdoor breezes with rooftop string lighting, cold mocha frappes, and student discount combos.', 'Near Shaukat Khanum, Johar Town', 'Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2705, 31.4655), 4326)::geography, '+92 322 8889900', '04:00 PM - 02:00 AM'),
  (59, 'Loafology', 'loafology-dha4', 'European artisan bakery and café famed for pure sourdough breads and clean organic brunches.', 'Heaven for sourdough lovers with Polish-style baked pastries, avocado poached eggs, and pour-overs.', 'Sector FF, Commercial Area, DHA Phase 4', 'DHA Phase 4', 'Lahore', ST_SetSRID(ST_MakePoint(74.3860, 31.4715), 4326)::geography, '+92 300 0770001', '08:00 AM - 11:00 PM'),
  (60, 'MYSA Specialty Coffee', 'mysa-specialty-coffee-dha', 'Scandinavian hygge-inspired coffee lounge prioritizing mindful sips and single-origin roasts.', 'Hygge-styled tranquil living room ambiance with artisan pour-overs and zero-noise study zones.', 'Sector CCA, DHA Phase 5', 'DHA', 'Lahore', ST_SetSRID(ST_MakePoint(74.4085, 31.4708), 4326)::geography, '+92 300 0009988', '08:00 AM - 11:30 PM');

-- PLACES 61 to 80 (DESI / PAKISTANI)
INSERT INTO public.places (id, name, slug, description, why_this_spot_is_good, address, area, city, location, phone, opening_hours)
VALUES
  (61, 'Haveli Restaurant', 'haveli-restaurant-walled-city', 'Historic multi-level rooftop heritage restaurant facing the majestic Badshahi Mosque.', 'Unbeatable illuminated views of Badshahi Mosque at night while dining on charcoal mutton chops and seekh kebabs.', 'Badshahi Mosque View, Fort Road Food Street, Walled City', 'Fort Road Food Street, Walled City', 'Lahore', ST_SetSRID(ST_MakePoint(74.3135, 31.5898), 4326)::geography, '+92 300 8414899', '01:00 PM - 01:00 AM'),
  (62, 'Butt Karahi', 'butt-karahi-lakshmi', 'The undisputed temple of Desi Ghee mutton karahi at the historic Lakshmi Chowk.', 'World-famous sizzling Desi Ghee mutton karahi cooked fresh in heavy black woks with ginger and green chilies.', 'Lakshmi Chowk, McLeod Road', 'Lakshmi Chowk', 'Lahore', ST_SetSRID(ST_MakePoint(74.3218, 31.5645), 4326)::geography, '+92 42 37233888', '12:00 PM - 03:00 AM'),
  (63, 'Waris Nihari', 'waris-nihari-anarkali', 'Legendary breakfast and late-night nihari institution simmering beef shank for over 50 years.', 'Rich slow-simmered beef marrow nihari finished with hot spiced tarka and fresh oven-baked khameeri rotis.', 'Paisa Akhbar, Anarkali / Circular Road', 'Anarkali / Circular Road', 'Lahore', ST_SetSRID(ST_MakePoint(74.3140, 31.5650), 4326)::geography, '+92 42 37320099', '06:00 AM - 12:00 AM'),
  (64, 'Salt’n Pepper Village', 'salt-n-pepper-village-gulberg', 'Iconic Pakistani cultural buffet village serving open-air live tandoor and karahi specialties.', 'Immersive traditional village scenery with live puppet shows, piping hot tandoori naans, and 50+ desi dishes.', '103 B-2 MM Alam Road, Gulberg III', 'MM Alam Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3510, 31.5120), 4326)::geography, '+92 42 35750735', '12:30 PM - 12:00 AM'),
  (65, 'Dera Restaurant', 'dera-restaurant-gaddafi', 'Open-air traditional charpai dining offering charcoal BBQ and handi beside Gaddafi Stadium.', 'Authentic Punjabi folk vibe with open-air charpai seating, live ghazal music, and tender reshmi kebabs.', 'Near Gaddafi Stadium, Ferozepur Road, Gulberg III', 'Near Gaddafi Stadium, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3380, 31.5125), 4326)::geography, '+92 42 35785566', '06:00 PM - 02:00 AM'),
  (66, 'Chandni Chowk Restaurant', 'chandni-chowk-gulberg', 'Extensive Pakistani and Mughlai buffet restaurant offering live barbecue and seafood.', 'Famous for massive buffet selections, fresh mutton ribs, live chaat counters, and family gatherings.', 'Gurumangat Road, Gulberg III', 'Gurumangat Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3580, 31.5200), 4326)::geography, '+92 42 35750000', '12:30 PM - 12:00 AM'),
  (67, 'Golden Shinwari Restaurant', 'golden-shinwari-gulberg', 'Traditional Pashtun Shinwari kitchen cooking meat using only animal fat and rock salt.', 'Pure authentic Shinwari lamb karahi and dumpukht cooked with zero artificial spices to let meat flavors shine.', 'Main Market, Gulberg II', 'Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3480, 31.5250), 4326)::geography, '+92 300 4488990', '12:00 PM - 02:00 AM'),
  (68, 'Ziafat', 'ziafat-gulberg', 'Famous traditional lunch and dinner buffet serving classic Lahori curries and BBQ.', 'Hearty authentic Lahori buffet with endless mutton biryani, chicken ginger, and warm gulab jamuns.', 'College Road, Gulberg II', 'College Road, Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3520, 31.5240), 4326)::geography, '+92 42 35753377', '12:30 PM - 11:30 PM'),
  (69, 'Muhammadi Nahari House', 'muhammadi-nahari-johar', 'Celebrated Johar Town branch of Lahore famous beef and mutton nihari specialists.', 'Golden glistening bone marrow nihari with fiery red oil, slivered ginger, and lemon wedges.', 'Commercial Area, Block G, Johar Town', 'Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2725, 31.4680), 4326)::geography, '+92 42 35311222', '07:00 AM - 01:00 AM'),
  (70, 'Masalawala by Qasar-e-Noor', 'masalawala-gulberg', 'High-end traditional street food and desi luxury kitchen with live counter experience.', 'Lavish heritage food festival atmosphere serving live kat-a-kat, crispy puris, and butter handis.', 'Sir Syed Road, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3518, 31.5155), 4326)::geography, '+92 42 35759900', '12:30 PM - 12:00 AM'),
  (71, 'Bagh – The Desi Experience', 'bagh-the-desi-experience-gulberg', 'Royal outdoor botanical garden serving gourmet Pakistani delicacies and clay pot handis.', 'Lush enchanting outdoor garden with charcoal-roasted kebabs and royal mutton dum biryani.', 'Block B-1, Gulberg III', 'Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3530, 31.5160), 4326)::geography, '+92 300 1112244', '06:00 PM - 01:00 AM'),
  (72, 'Desi Table - Lahore', 'desi-table-gulberg', 'Modern Punjabi dining destination focusing on regional thalis and copper-pot gravies.', 'Artisanal copper-ware service with rich butter chicken, garlic naans, and creamy dal makhani.', 'Main Gulberg Road', 'Main Gulberg Road', 'Lahore', ST_SetSRID(ST_MakePoint(74.3495, 31.5185), 4326)::geography, '+92 42 35758833', '01:00 PM - 12:00 AM'),
  (73, 'Desi Oven Gulberg', 'desi-oven-gulberg', 'Clay-oven specialist known for stuffed kulchas, tandoori boti, and slow-roasted meats.', 'Warm aroma of tandoori spice with stuffed cheese kulchas and smoky chicken boti skewers.', 'College Road, Gulberg II', 'College Road, Gulberg II', 'Lahore', ST_SetSRID(ST_MakePoint(74.3515, 31.5238), 4326)::geography, '+92 42 35754400', '12:00 PM - 12:30 AM'),
  (74, 'Desi Oven - DHA Phase 1', 'desi-oven-dha1', 'DHA outpost of Desi Oven serving fresh clay-tandoor flatbreads and grilled chicken.', 'Convenient DHA takeaway and dine-in for fresh bubbling naans and melt-in-mouth malai boti.', 'Sector G, Commercial Area, DHA Phase 1', 'DHA Phase 1', 'Lahore', ST_SetSRID(ST_MakePoint(74.3750, 31.4880), 4326)::geography, '+92 42 35748899', '12:00 PM - 01:00 AM'),
  (75, 'Desi Pardesi Restaurant', 'desi-pardesi-shadman', 'Family dining venue on Jail Road offering hearty portions of karahi, BBQ, and biryani.', 'Warm family hospitality on Jail Road with spicy mutton chops, chicken achari, and roghni naans.', 'Jail Road, Shadman', 'Jail Road, Shadman', 'Lahore', ST_SetSRID(ST_MakePoint(74.3310, 31.5380), 4326)::geography, '+92 42 37421100', '12:30 PM - 12:00 AM'),
  (76, 'Pakistan Restaurant', 'pakistan-restaurant-johar', 'Student and family staple near UMT serving traditional dal, chicken karahi, and fresh tandoor.', 'Unbeatable budget-friendly desi comfort food with piping hot roti and spicy chicken karahi near UMT.', 'UMT Road, Johar Town', 'UMT Road, Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2690, 31.4640), 4326)::geography, '+92 42 35314488', '10:00 AM - 01:00 AM'),
  (77, 'Zaiqa Restaurant & Biryani House', 'zaiqa-biryani-model-town', 'Model Town classic serving fragrant Karachi-style beef biryani, haleem, and chicken tikka.', 'Famous for aromatic spiced dum biryani with tender potatoes and fiery seekh kebabs.', 'Link Road, Model Town', 'Model Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.3220, 31.4915), 4326)::geography, '+92 42 35843322', '11:00 AM - 12:00 AM'),
  (78, 'Bundu Khan Restaurant - Gulberg', 'bundu-khan-gulberg', 'Legendary national barbecue brand famous for Bihari boti, chicken tikka, and puri paratha.', 'The gold standard of Pakistani barbecue featuring tender beef bihari boti and golden crispy puri parathas.', 'Liberty Market, Gulberg III', 'Gulberg / Johar Town / DHA', 'Lahore', ST_SetSRID(ST_MakePoint(74.3465, 31.5122), 4326)::geography, '+92 42 111444666', '12:00 PM - 01:00 AM'),
  (79, 'Bar-B-Q Tonight', 'bar-b-q-tonight-gulberg', 'Renowned nationwide barbecue house serving succulent afghani boti, mutton ribs, and seafood.', 'Vast family dining rooms with charcoal-smoked Afghani boti, juicy jumbo prawns, and fresh tandoor naans.', 'Mian Mehmood Ali Kasoori Road, Gulberg III', 'Mian Mehmood Ali Kasoori Road, Gulberg III', 'Lahore', ST_SetSRID(ST_MakePoint(74.3565, 31.5118), 4326)::geography, '+92 42 35759900', '12:30 PM - 01:00 AM'),
  (80, 'Buqayvia Restaurant', 'buqayvia-restaurant-johar', 'Canal Road dining venue offering open lawns, charcoal grilled mutton, and chicken handi.', 'Relaxed canal-side lawns for peaceful evening dinners featuring buttery chicken handi and grilled fish.', 'Main Canal Road, Johar Town', 'Main Canal Road, Johar Town', 'Lahore', ST_SetSRID(ST_MakePoint(74.2650, 31.4590), 4326)::geography, '+92 300 4455778', '01:00 PM - 01:00 AM');

